def firstNegativeInWindows(nums, k):
    from collections import deque
    neg = deque()
    res = []
    for i, x in enumerate(nums):
        if x < 0:
            neg.append(i)
        if i >= k - 1:
            while neg and neg[0] <= i - k:
                neg.popleft()
            res.append(nums[neg[0]] if neg else 0)
    return res
